changeSet.sql:
-- Darker overall lighting + denser cave fog UPDATE scene_elements SET properties = '{"ambientColorR":0.35,"ambientColorG":0.42,"ambientColorB":0.55,"ambientEnergy":0.35,"fogDensity":0.012,"fogR":0.12,"fogG":0.16,"fogB":0.22}' WHERE level_id = 1 AND element_type = 'world_env';
-- Reduce the wide ambient fill so torch / shaft light has contrast UPDATE scene_elements SET properties = '{"colorR":0.35,"colorG":0.42,"colorB":0.55,"energy":0.5}' WHERE level_id = 1 AND element_type = 'ambient_light';
-- Cull half the broad fill_lights so shadows can settle in DELETE FROM scene_elements WHERE level_id = 1 AND element_type = 'fill_light' AND name IN ('FillLight2','FillLight3','FillLight4');
